package B::Showlex;our$VERSION='1.05';use strict;use B qw(svref_2object comppadlist class);use B::Terse ();use B::Concise ();our$walkHandle=\*STDOUT;sub walk_output {$walkHandle=B::Concise::walk_output(@_);$walkHandle}sub shownamearray {my ($name,$av)=@_;my@els=$av->ARRAY;my$count=@els;my$i;print$walkHandle "$name has $count entries\n";for ($i=0;$i < $count;$i++){my$sv=$els[$i];if (class($sv)ne "SPECIAL"){printf$walkHandle "$i: (0x%lx) %s\n",$$sv,$sv->PVX // "undef" || "const"}else {printf$walkHandle "$i: %s\n",$sv->terse}}}sub showvaluearray {my ($name,$av)=@_;my@els=$av->ARRAY;my$count=@els;my$i;print$walkHandle "$name has $count entries\n";for ($i=0;$i < $count;$i++){printf$walkHandle "$i: %s\n",$els[$i]->terse}}sub showlex {my ($objname,$namesav,$valsav)=@_;shownamearray("Pad of lexical names for $objname",$namesav);showvaluearray("Pad of lexical values for $objname",$valsav)}my ($newlex,$nosp1);sub padname_terse {my$name=shift;return$name->terse if class($name)eq 'SPECIAL';my$str=$name->PVX;return sprintf "(0x%lx) %s",$$name,length$str ? qq'"$str"' : defined$str ? "const" : 'undef'}sub newlex {my ($objname,$names,$vals)=@_;my@names=$names->ARRAY;my@vals=$vals->ARRAY;my$count=@names;print$walkHandle "$objname Pad has $count entries\n";printf$walkHandle "0: %s\n",padname_terse($names[0])unless$nosp1;for (my$i=1;$i < $count;$i++){printf$walkHandle "$i: %s = %s\n",padname_terse($names[$i]),$vals[$i]->terse,unless$nosp1 and class($names[$i])eq 'SPECIAL' ||!$names[$i]->LEN}}sub showlex_obj {my ($objname,$obj)=@_;$objname =~ s/^&main::/&/;showlex($objname,svref_2object($obj)->PADLIST->ARRAY)if!$newlex;newlex ($objname,svref_2object($obj)->PADLIST->ARRAY)if$newlex}sub showlex_main {showlex("comppadlist",comppadlist->ARRAY)if!$newlex;newlex ("main",comppadlist->ARRAY)if$newlex}sub compile {my@options=grep(/^-/,@_);my@args=grep(!/^-/,@_);for my$o (@options){$newlex=1 if$o eq "-newlex";$nosp1=1 if$o eq "-nosp"}return \&showlex_main unless@args;return sub {my$objref;for my$objname (@args){next unless$objname;if (ref$objname){print$walkHandle "B::Showlex::compile($objname)\n";$objref=$objname}else {$objname="main::$objname" unless$objname =~ /::/;print$walkHandle "$objname:\n";no strict 'refs';die "err: unknown function ($objname)\n" unless *{$objname}{CODE};$objref=\&$objname}showlex_obj($objname,$objref)}}}1;